def warp_cost(addresses, line=128, sector=32):
    """Return (lines, sectors): how many distinct 128-byte lines and 32-byte sectors the byte addresses touch."""
    lines = {a // line for a in addresses}
    sectors = {a // sector for a in addresses}
    return len(lines), len(sectors)

